const output = $json.output;
const hasAction = output.action_type && output.action_type !== 'none';
const proposedAction = hasAction ? {
  action_type: output.action_type,
  daily_budget_usd: output.action_type === 'update_daily_budget' ? output.daily_budget_usd : null,
  reason: output.reason,
} : null;
return [{ json: {
  content: output.reply,
  proposedAction,
  actionStatus: hasAction ? 'proposed' : null,
} }];
